import { render, screen, waitFor } from '@testing-library/react';
import userEvent from '@testing-library/user-event';
import { axe, toHaveNoViolations } from 'jest-axe';
import { describe, it, expect, vi, beforeEach } from 'vitest';
import { Checkout } from './Checkout';

expect.extend(toHaveNoViolations);

// Arrange: Mock context providers
const mockCartContext = {
  items: [{ id: '1', name: 'Widget', price: 29.99, quantity: 2 }],
  total: 59.98,
  clearCart: vi.fn(),
};

const mockPaymentContext = {
  processPayment: vi.fn(),
};

const renderCheckout = (props = {}) => {
  return render(
    <CartProvider value={mockCartContext}>
      <PaymentProvider value={mockPaymentContext}>
        <Checkout {...props} />
      </PaymentProvider>
    </CartProvider>
  );
};

describe('Checkout Component', () => {
  beforeEach(() => {
    vi.clearAllMocks();
  });

  describe('Happy Path - Complete Checkout Flow', () => {
    it('navigates through all steps and displays confirmation', async () => {
      const user = userEvent.setup();
      const onComplete = vi.fn();
      mockPaymentContext.processPayment.mockResolvedValue({ orderId: 'ORD-123' });

      renderCheckout({ onComplete });

      // Shipping step
      await user.type(screen.getByRole('textbox', { name: /street/i }), '123 Main St');
      await user.type(screen.getByRole('textbox', { name: /city/i }), 'Springfield');
      await user.type(screen.getByRole('textbox', { name: /state/i }), 'IL');
      await user.type(screen.getByRole('textbox', { name: /zip/i }), '62701');
      await user.click(screen.getByRole('button', { name: /continue to payment/i }));

      // Payment step
      await user.type(screen.getByRole('textbox', { name: /card number/i }), '4111111111111111');
      await user.type(screen.getByRole('textbox', { name: /expiry/i }), '12/25');
      await user.type(screen.getByRole('textbox', { name: /cvv/i }), '123');
      await user.type(screen.getByRole('textbox', { name: /name on card/i }), 'John Doe');
      await user.click(screen.getByRole('button', { name: /review order/i }));

      // Review step
      await user.click(screen.getByRole('button', { name: /place order/i }));

      // Assert confirmation
      await waitFor(() => {
        expect(screen.getByText(/order confirmed/i)).toBeInTheDocument();
        expect(screen.getByText('ORD-123')).toBeInTheDocument();
      });
      expect(onComplete).toHaveBeenCalledWith('ORD-123');
    });
  });

  describe('Form Validation', () => {
    it('displays error when ZIP code format is invalid', async () => {
      const user = userEvent.setup();
      renderCheckout();

      await user.type(screen.getByRole('textbox', { name: /zip/i }), 'invalid');
      await user.click(screen.getByRole('button', { name: /continue/i }));

      expect(screen.getByText(/valid zip code required/i)).toBeInTheDocument();
    });

    it('displays error for invalid card number', async () => {
      const user = userEvent.setup();
      renderCheckout();
      // Navigate to payment step first...

      await user.type(screen.getByRole('textbox', { name: /card number/i }), '1234');
      await user.click(screen.getByRole('button', { name: /review/i }));

      expect(screen.getByText(/valid 16-digit card number required/i)).toBeInTheDocument();
    });
  });

  describe('Edge Cases', () => {
    it('displays empty cart message when no items present', () => {
      mockCartContext.items = [];
      renderCheckout();

      expect(screen.getByText(/your cart is empty/i)).toBeInTheDocument();
    });
  });

  describe('Accessibility', () => {
    it('has no accessibility violations', async () => {
      const { container } = renderCheckout();
      const results = await axe(container);
      expect(results).toHaveNoViolations();
    });
  });
});
